text:
.hub-footer {
  grid-area: footer;

  & .center-column {
    justify-content: center;
  }

  & hr {
    border: none;
    height: 1px;
    margin-block-start: var(--hub-footer-margin-block);
    background: linear-gradient(to right, transparent, var(--color-surface-border), transparent);
    color: transparent;
  }

  & .footer-button {
    font-size: 1.1rem;
    min-width: 128px;
    padding: 10px 25px;
    text-align: center;
  }

  .busy & {
    z-index: 3;
  }
}
